class ThreadLifecycleDemo {
    static void run() throws InterruptedException {
        Thread worker = new Thread(() -> {
            try {
                Thread.sleep(50);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });
        System.out.println("Before start: " + worker.getState());
        worker.start();
        System.out.println("After start: " + worker.getState());
        worker.join();
        System.out.println("After join: " + worker.getState());
    }
}

class Counter {
    private int count = 0;

    synchronized void increment() {
        count++;
    }

    synchronized int get() {
        return count;
    }
}

class RaceConditionDemo {
    static void run() throws InterruptedException {
        Counter counter = new Counter();
        Runnable task = () -> {
            for (int i = 0; i < 1000; i++) {
                counter.increment();
            }
        };
        Thread t1 = new Thread(task);
        Thread t2 = new Thread(task);
        t1.start();
        t2.start();
        t1.join();
        t2.join();
        System.out.println(counter.get());
    }
}

import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.ConcurrentHashMap;
import java.util.Map;

class AtomicVsLockDemo {
    private final Object lock = new Object();      // monitor rieng, khong khoa 'this'
    private int guarded = 0;
    private final AtomicInteger lockFree = new AtomicInteger();
    private final Map<String, Integer> hits = new ConcurrentHashMap<>();

    void work(String key) {
        synchronized (lock) {                       // pham vi khoa hep
            guarded++;
        }
        lockFree.incrementAndGet();                 // CAS, khong can khoa
        hits.merge(key, 1, Integer::sum);           // thao tac nguyen tu san co
    }

    public static void main(String[] args) throws InterruptedException {
        AtomicVsLockDemo demo = new AtomicVsLockDemo();
        Runnable task = () -> { for (int i = 0; i < 1000; i++) demo.work("a"); };
        Thread t1 = new Thread(task);
        Thread t2 = new Thread(task);
        t1.start(); t2.start();
        t1.join(); t2.join();                       // cho ca hai xong truoc khi doc
        System.out.println(demo.guarded + " " + demo.lockFree.get() + " " + demo.hits);
    }
}

