import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

class ExecutorDemo {
    static void run() throws InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(2);
        executor.submit(() -> System.out.println("task 1"));
        executor.submit(() -> System.out.println("task 2"));
        executor.shutdown();
        executor.awaitTermination(1, TimeUnit.SECONDS);
    }
}

import java.util.concurrent.*;
import java.util.List;

class ExecutorPatternsDemo {
    public static void main(String[] args) throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(2);
        try {
            // invokeAll: chay nhieu tac vu, cho tat ca hoan thanh
            List<Callable<Integer>> tasks = List.of(() -> 1, () -> 2, () -> { throw new IllegalStateException("boom"); });
            List<Future<Integer>> futures = pool.invokeAll(tasks);

            for (Future<Integer> f : futures) {
                try {
                    System.out.println("ok " + f.get());   // blocking
                } catch (ExecutionException e) {
                    // loi cua tac vu duoc boc trong ExecutionException
                    System.out.println("task failed: " + e.getCause().getMessage());
                }
            }
        } finally {
            pool.shutdown();                                // khong nhan tac vu moi
            if (!pool.awaitTermination(2, TimeUnit.SECONDS)) {
                pool.shutdownNow();                         // ngat cac tac vu con lai
            }
        }
    }
}

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;

class FileOpsDemo {
    static void run(Path source, Path target) throws IOException {
        if (!Files.exists(source)) {
            Files.createFile(source);
        }
        Files.copy(source, target, StandardCopyOption.REPLACE_EXISTING);
        Files.deleteIfExists(source);
    }
}

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.List;
import java.util.stream.Stream;

class FilesPatternsDemo {
    public static void main(String[] args) throws IOException {
        Path dir = Files.createTempDirectory("demo");
        Path file = dir.resolve("data.txt");                 // ghep duong dan an toan

        // luon chi dinh charset tuong minh
        Files.writeString(file, "line1\nline2\n", StandardCharsets.UTF_8);

        // file nho: doc het mot lan
        List<String> all = Files.readAllLines(file, StandardCharsets.UTF_8);
        System.out.println(all.size());

        // file lon: stream lazy, PHAI dong -> try-with-resources
        try (Stream<String> lines = Files.lines(file, StandardCharsets.UTF_8)) {
            System.out.println(lines.filter(l -> l.endsWith("2")).count());
        }

        // ghi them thay vi ghi de
        Files.writeString(file, "line3\n", StandardCharsets.UTF_8, StandardOpenOption.APPEND);

        try {
            Files.readString(dir.resolve("missing.txt"));
        } catch (NoSuchFileException e) {
            System.out.println("loi co kieu ro rang: " + e.getFile());
        }

        Files.deleteIfExists(file);
        Files.deleteIfExists(dir);
    }
}

import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.Serializable;

class Address implements Serializable {
    private static final long serialVersionUID = 1L;

    private final String city;

    Address(String city) {
        this.city = city;
    }
}

class Employee implements Serializable {
    private static final long serialVersionUID = 1L;

    private final String name;
    private final Address address;
    private transient String cachedDisplayName;

    Employee(String name, Address address) {
        this.name = name;
        this.address = address;
    }

    private void writeObject(ObjectOutputStream out) throws IOException {
        out.defaultWriteObject();
    }

    private void readObject(ObjectInputStream in) throws IOException, ClassNotFoundException {
        in.defaultReadObject();
        cachedDisplayName = name.toUpperCase();
    }
}

